function bankingB64(string $s):string {return rtrim(strtr(base64_encode($s),'+/','-_'),'=');}
function bankingSetupStatus(array $config):array {
 $missing=[];foreach(['banking_enabled','banking_live_approved'] as $k)if(!filter_var($config[$k]??false,FILTER_VALIDATE_BOOLEAN))$missing[]=$k;
 foreach(['banking_app_id','banking_private_key','banking_redirect_uri'] as $k)if(trim((string)($config[$k]??''))==='')$missing[]=$k;
 return ['ready'=>!$missing,'missing'=>$missing,'status'=>$missing?'Nicht verbunden – Anbieterfreigabe/Einrichtung erforderlich':'Anbieter konfiguriert – Bankautorisierung noch erforderlich'];
}
function bankingRedirect(string $url,bool $callback=false):string {
 $u=parse_url($url);if(strlen($url)>4096||preg_match('/[\x00-\x20\x7f]/',$url)||!$u||($u['scheme']??'')!=='https'||empty($u['host'])||isset($u['user'])||isset($u['pass'])||isset($u['fragment'])||($u['port']??443)!==443)throw new RuntimeException('GSZ_BANK_REDIRECT_INVALID');
 if(!$callback&&strtolower($u['host'])!=='auth.enablebanking.com')throw new RuntimeException('GSZ_BANK_REDIRECT_HOST');return $url;
}
