  $get=$method==='GET'&&preg_match('#^/(?:aspsps\?country=DE&service=AIS|sessions/[a-zA-Z0-9-]{1,100}|accounts/[a-zA-Z0-9-]{1,100}/(?:balances|transactions)(?:\?[a-zA-Z0-9_%=&.~-]+)?)$#D',$path);$post=$method==='POST'&&in_array($path,['/auth','/sessions'],true);if(!$get&&!$post)throw new RuntimeException('GSZ_BANK_READ_ONLY');if(++$this->requests>12||microtime(true)-$this->started>25)throw new RuntimeException('GSZ_BANK_REQUEST_LIMIT');$jwt=$this->jwt();$result=$this->transport?($this->transport)($method,$path,$body,$jwt):$this->http($method,$path,$body,$jwt);if(!is_array($result))throw new RuntimeException('GSZ_BANK_RESPONSE_INVALID');return $result;
