 public function institutions():array {$r=$this->request('GET','/aspsps?country=DE&service=AIS');$list=$r['aspsps']??null;if(!is_array($list)||count($list)>5000)throw new RuntimeException('GSZ_BANK_INSTITUTIONS_FORMAT');$out=[];foreach($list as $bank)if(($bank['country']??'')==='DE'&&is_string($bank['name']??null)&&mb_strlen($bank['name'])<=190)$out[]=['name'=>$bank['name'],'country'=>'DE','psu_types'=>$bank['psu_types']??[]];return $out;}
 public function authorize(string $bank,string $state,string $type):string {if(!in_array($type,['business','personal'],true)||!preg_match('/^[a-f0-9]{64}$/D',$state)||$bank===''||mb_strlen($bank)>190)throw new RuntimeException('GSZ_BANK_AUTH_REQUEST');$r=$this->request('POST','/auth',['access'=>['valid_until'=>gmdate('Y-m-d\TH:i:s\Z',time()+90*86400)],'aspsp'=>['name'=>$bank,'country'=>'DE'],'state'=>$state,'redirect_url'=>$this->config['banking_redirect_uri'],'psu_type'=>$type,'language'=>'de']);return bankingRedirect((string)($r['url']??''));}
 public function exchange(string $code):array {if(strlen($code)<1||strlen($code)>2048||preg_match('/[\x00-\x20\x7f]/',$code))throw new RuntimeException('GSZ_BANK_CODE_INVALID');$r=$this->request('POST','/sessions',['code'=>$code]);if(!is_string($r['session_id']??null)||!preg_match('/^[a-zA-Z0-9-]{1,100}$/D',$r['session_id'])||!is_array($r['accounts']??null)||count($r['accounts'])>50||strtotime($r['access']['valid_until']??'')<=time())throw new RuntimeException('GSZ_BANK_SESSION_FORMAT');return $r;}
 public function transactions(string $account,string $from,string $to):array {if(!zgsValidDate($from)||!zgsValidDate($to)||$from>$to||(new DateTimeImmutable($from))->diff(new DateTimeImmutable($to))->days>366)throw new RuntimeException('Bankabrufzeitraum maximal366Tage.');$rows=[];$continuation=null;$seen=[];for($page=0;$page<8;$page++){$query=['date_from'=>$from,'date_to'=>$to,'transaction_status'=>'BOOK'];if($continuation!==null)$query['continuation_key']=$continuation;$r=$this->request('GET','/accounts/'.$account.'/transactions?'.http_build_query($query,'','&',PHP_QUERY_RFC3986));if(!is_array($r['transactions']??null))throw new RuntimeException('GSZ_BANK_TRANSACTIONS_FORMAT');foreach($r['transactions'] as $t){$rows[]=bankingProviderRow($t);if(count($rows)>1000)throw new RuntimeException('Bankabruf maximal1000Umsätze; Zeitraum kürzen.');}$continuation=$r['continuation_key']??null;if($continuation===null||$continuation==='')return $rows;if(!is_string($continuation)||strlen($continuation)>512||isset($seen[$continuation]))throw new RuntimeException('GSZ_BANK_PAGINATION_INVALID');$seen[$continuation]=true;}throw new RuntimeException('GSZ_BANK_PAGINATION_LIMIT');}
