}
function bankingProviderRow(array $t):array {
 if(($t['status']??'')!=='BOOK'||!in_array($t['credit_debit_indicator']??'',['CRDT','DBIT'],true)||($t['transaction_amount']['currency']??'')!=='EUR')throw new RuntimeException('Nur eindeutig gebuchte EUR-Umsätze; keine vorgemerkten/fremden Währungen.');$id=(string)($t['entry_reference']??'');if($id==='')$id=(string)($t['transaction_id']??'');if($id===''||mb_strlen($id)>170)throw new RuntimeException('Stabile Bankreferenz fehlt. Keine künstliche Umsatz-ID.');$amount=financeCents((string)($t['transaction_amount']['amount']??''));if($amount<0)throw new RuntimeException('Providerbetrag muss positiv sein; Vorzeichen aus CRDT/DBIT.');if($t['credit_debit_indicator']==='DBIT')$amount=-$amount;$booked=(string)($t['booking_date']??'');$value=(string)($t['value_date']??$booked);if(!zgsValidDate($booked)||!zgsValidDate($value))throw new RuntimeException('GSZ_BANK_DATE_INVALID');$counterparty=(string)($t[$amount<0?'creditor':'debtor']['name']??'');$purpose=$t['remittance_information']??[];if(!is_array($purpose)||array_filter($purpose,fn($v)=>!is_string($v)))throw new RuntimeException('GSZ_BANK_PURPOSE_INVALID');$purpose=implode(' ',$purpose);$counterIban=(string)($t[$amount<0?'creditor_account':'debtor_account']['iban']??'');if($counterIban!=='')$purpose.=' [Gegenkonto: '.bankIban($counterIban).']';if(mb_strlen($purpose)>2000||mb_strlen($counterparty)>500)throw new RuntimeException('GSZ_BANK_TEXT_LIMIT');return ['id'=>$id,'booked_on'=>$booked,'value_on'=>$value,'amount'=>financeDecimal($amount),'currency'=>'EUR','purpose'=>$purpose,'counterparty'=>$counterparty];
}
/** Reuses the pre-existing read-only banking contract for one authorized account. */
final class GszEnableBankingAccount implements GszReadOnlyBankAdapter {
 public function __construct(private GszEnableBankingClient $client,private string $account){if(!preg_match('/^[a-zA-Z0-9-]{1,100}$/D',$account))throw new RuntimeException('GSZ_BANK_ACCOUNT_INVALID');}
 public function transactions(string $from,string $to):array {return $this->client->transactions($this->account,$from,$to);}
 public function balance():array {return $this->client->balances($this->account);}
}
